"""
全方位木DP (Rerooting DP / 汎用全方位木走査フレームワーク)
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
すべての頂点 v (0 ~ n-1) を根としたときの木DPの値を、累積積（左右からのマージ）を用いて O(N) で一括計算する。
例:
- 各頂点からの最遠頂点までの距離 (木の高さ)
- 各頂点を根としたときのパスの総和、重み付き総和など

【引数】
- n: 頂点数
- g: 隣接リスト [[to, ...], ...] (無向木)
- merge: 2つの部分木の結果を合成する二項演算 (モノイド積: e.g. max, add)
- e: merge の単位元 (e.g. 0)
- apply_edge: 子の部分木の値に親へ至る辺の重み・効果を適用する関数 (e.g. lambda val: val + 1)
"""

from collections import deque

# https://github.com/ddfkit/acsampl/blob/main/znhoui.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def rerooting(n,g,merge,e,apply_edge):
    order=[];par=[-1]*n;q=deque([0])
    while q:
        u=q.popleft();order.append(u)
        for v in g[u]:
            if v!=par[u]:par[v]=u;q.append(v)
    dp_sub=[e]*n
    for u in reversed(order):
        val=e
        for v in g[u]:
            if v!=par[u]:val=merge(val,apply_edge(dp_sub[v]))
        dp_sub[u]=val
    ans=[e]*n;dp_p=[e]*n
    for u in order:
        deg=len(g[u]);children=[v for v in g[u] if v!=par[u]]
        left=[e]*(len(children)+1);right=[e]*(len(children)+1)
        for i,v in enumerate(children):
            left[i+1]=merge(left[i],apply_edge(dp_sub[v]))
        for i in range(len(children)-1,-1,-1):
            right[i]=merge(right[i+1],apply_edge(dp_sub[children[i]]))
        ans[u]=merge(left[-1],apply_edge(dp_p[u]) if par[u]>=0 else e)
        for i,v in enumerate(children):
            ex_child=merge(left[i],right[i+1])
            if par[u]>=0:ex_child=merge(ex_child,apply_edge(dp_p[u]))
            dp_p[v]=ex_child
    return ans

if __name__ == "__main__":
    # ========= サンプル木 =========
    # 0 - 1 - 2 - 3
    # 0. 根付き木にして、親 par と BFS 順 order と children を作る
    # 1. bottom-up: 部分木ごとの集約値 dp_sub をボトムアップに計算
    # 2. prefix / suffix: 左右からの累積値を作成し、O(1) で「ある子以外のマージ値」を取得可能にする
    # 3. top-down: 親側からの伝播値 dp_p をトップダウンに計算
    # 4. 各頂点 v に対し、全方向からの寄与をマージして「vからもっとも遠い頂点までの距離 (木の高さ)」を求める
    N = 4
    g = [[1], [0, 2], [1, 3], [2]]
    heights = rerooting(N, g, max, 0, lambda x: x + 1)
    assert heights == [3, 2, 2, 3]

    # より分岐のある木でのテスト
    #         0
    #      /  |  \
    #     1   2   3
    #    / \
    #   4   5
    N2 = 6
    g2 = [[1, 2, 3], [0, 4, 5], [0], [0], [1], [1]]
    h2 = rerooting(N2, g2, max, 0, lambda x: x + 1)
    # 0からの最遠: 4 or 5 で距離2
    assert h2[0] == 2
    # 4からの最遠: 2 or 3 で距離3 (4->1->0->2)
    assert h2[4] == 3
    print("znhoui.py: all tests passed!")
